#!/usr/bin/env python3
"""Command line driver for the jd-compatible JSON diff implementation."""
from __future__ import annotations

import json
import os
import sys

VERSION = "jd version 2.5.0"


def _usage():
    return """Usage: jd [OPTION]... FILE1 [FILE2]
Diff and patch JSON files.

Prints the diff of FILE1 and FILE2 to STDOUT.
When FILE2 is omitted the second input is read from STDIN.
When patching (-p) FILE1 is a diff.

Options:
  -color       Print color diff.
  -color-words Print color diff with character-level highlighting.
  -p           Apply patch FILE1 to FILE2 or STDIN.
  -o=FILE3     Write to FILE3 instead of STDOUT.
  -opts='[]'   JSON array of comparison options.
  -set         Treat arrays as sets.
  -mset        Treat arrays as multisets.
  -setkeys     Keys to identify set objects.
  -yaml        Read and write YAML instead of JSON.
  -precision=N Maximum absolute difference for numbers to be equal.
  -f=FORMAT    Diff format: jd, patch, merge.
  -t=FORMATS   Translate formats, e.g. jd2patch or yaml2json.
  -version     Print version and exit.
"""


def _parse_args(argv):
    flags = {"color": False, "color_words": False, "patch": False,
             "yaml": False, "set": False, "mset": False, "version": False,
             "git": False, "opts": "[]", "precision": None, "setkeys": None,
             "format": "jd", "translate": None, "output": None, "port": None}
    files = []
    i = 0
    while i < len(argv):
        a = argv[i]
        if a == "--":
            files.extend(argv[i + 1:]); break
        if not a.startswith("-") or a == "-":
            files.append(a); i += 1; continue
        key, eq, value = a.partition("=")
        name = key.lstrip("-")
        bools = {"color": "color", "color-words": "color_words", "p": "patch",
                 "yaml": "yaml", "set": "set", "mset": "mset",
                 "version": "version", "git-diff-driver": "git", "v2": "v2"}
        vals = {"opts": "opts", "precision": "precision", "setkeys": "setkeys",
                "f": "format", "t": "translate", "o": "output", "port": "port"}
        if name in bools:
            if eq:
                raise ValueError("flag does not take a value: " + key)
            flags[bools[name]] = True
        elif name in vals:
            if not eq:
                i += 1
                if i >= len(argv): raise ValueError("flag needs an argument: " + key)
                value = argv[i]
            target = vals[name]
            if target == "precision":
                try: value = float(value)
                except ValueError: raise ValueError("invalid precision")
            if target == "port":
                try: value = int(value)
                except ValueError: raise ValueError("invalid port")
            flags[target] = value
        else:
            raise ValueError("flag provided but not defined: " + key)
        i += 1
    return flags, files


def _load(text):
    return json.loads(text, parse_constant=lambda x: (_ for _ in ()).throw(ValueError("invalid constant " + x)))


def _read(path):
    if path == "-": return sys.stdin.read()
    with open(path, "r", encoding="utf-8") as f: return f.read()


def _write(path, value):
    if path:
        with open(path, "w", encoding="utf-8") as f: f.write(value)
    else: sys.stdout.write(value)


def _apply_jd_patch(doc, patch):
    """Apply the common scalar/object/array subset of jd's line patch syntax."""
    import copy
    value = copy.deepcopy(doc)
    hunks = []
    path = None
    rows = []
    for line in patch.splitlines():
        if line.startswith("@ "):
            if path is not None: hunks.append((path, rows))
            path, rows = json.loads(line[2:]), []
        elif line.startswith("^ "):
            continue
        elif line.startswith(("  ", "+ ", "- ")) and path is not None:
            rows.append((line[:1], json.loads(line[2:])))
    if path is not None: hunks.append((path, rows))
    for path, rows in hunks:
        if not path:
            minus = [v for s, v in rows if s == "-"]
            plus = [v for s, v in rows if s == "+"]
            if minus: value = plus[-1] if plus else None
            elif plus: value = plus[-1]
            continue
        parent = value
        for part in path[:-1]:
            parent = parent[part]
        key = path[-1]
        minus = [v for s, v in rows if s == "-"]
        plus = [v for s, v in rows if s == "+"]
        if isinstance(parent, dict):
            if minus: parent.pop(key, None)
            if plus: parent[key] = plus[-1]
        elif isinstance(parent, list) and isinstance(key, int):
            idx = key
            if minus:
                for old in minus:
                    if idx < len(parent) and parent[idx] == old: parent.pop(idx)
                    else:
                        try: parent.remove(old)
                        except ValueError: pass
            for offset, new in enumerate(plus): parent.insert(min(idx + offset, len(parent)), new)
    return value


def main(argv=None):
    argv = sys.argv[1:] if argv is None else argv
    if not argv:
        sys.stdout.write("\n" + _usage() + "\nVersion: 2.5.0\n\n")
        return 2
    try:
        flags, files = _parse_args(argv)
    except ValueError as e:
        sys.stderr.write(str(e) + "\n")
        return 2
    if flags["version"]:
        print(VERSION); return 0
    if len(files) > 2 or (not files and not flags["translate"]):
        sys.stdout.write("\n" + _usage() + "\nVersion: 2.5.0\n\n"); return 2
    if flags["translate"]:
        from translate import translate
        source = _read(files[0]) if files else sys.stdin.read()
        result = translate(source, flags["translate"], yaml_mode=flags["yaml"])
        _write(flags["output"], result)
        return 0
    if not files:
        sys.stdout.write("\n" + _usage() + "\nVersion: 2.5.0\n\n"); return 2
    first_path = files[0]
    try:
        first_text = _read(first_path)
        second_text = _read(files[1]) if len(files) == 2 else sys.stdin.read()
        options = json.loads(flags["opts"])
        if not isinstance(options, list): raise ValueError("options must be a JSON array")
        if flags["set"]: options.append("SET")
        if flags["mset"]: options.append("MULTISET")
        if flags["precision"] is not None: options.append({"precision": flags["precision"]})
        if flags["setkeys"] is not None:
            try: keys = json.loads(flags["setkeys"])
            except Exception: keys = [x for x in flags["setkeys"].split(",") if x]
            options.append({"setkeys": keys})
        if flags["patch"]:
            if flags["yaml"]:
                from yamlutil import loads as yaml_loads, dumps
                base = yaml_loads(second_text)
            else:
                base = _load(second_text)
            patched = _apply_jd_patch(base, first_text)
            result = dumps(patched) if flags["yaml"] else json.dumps(patched, ensure_ascii=False, separators=(",", ":"))
            _write(flags["output"], result)
            return 0
        if flags["yaml"]:
            from yamlutil import loads as yaml_loads
            a, b = yaml_loads(first_text), yaml_loads(second_text)
        else:
            a, b = _load(first_text), _load(second_text)
        from diffcore import render_diff
        result = render_diff(a, b, options)
        if result:
            result = '^ {"file":' + json.dumps(first_path, ensure_ascii=False) + '}\n' + result
        if flags["color"] or flags["color_words"]:
            from colorize import colorize
            result = colorize(result, words=flags["color_words"])
        _write(flags["output"], result)
        return 1 if render_diff(a, b, options) else 0
    except Exception as e:
        sys.stderr.write(str(e) + "\n")
        return 2


if __name__ == "__main__":
    raise SystemExit(main())
