"""Generate RFC 6902 and RFC 7386 representations of a JSON change."""
import json
from difflib import SequenceMatcher


def _json(value):
    return json.dumps(value, ensure_ascii=False, separators=(",", ":"), allow_nan=False, sort_keys=True)


def _pointer(parts):
    return "".join("/" + str(p).replace("~", "~0").replace("/", "~1") for p in parts)


def merge_patch(before, after):
    """Return a JSON Merge Patch value that transforms before into after."""
    if isinstance(before, dict) and isinstance(after, dict):
        patch = {}
        for key in sorted(before.keys() - after.keys()):
            patch[key] = None
        for key in sorted(after):
            if key not in before:
                patch[key] = after[key]
            else:
                value = merge_patch(before[key], after[key])
                if value is not _NO_CHANGE:
                    patch[key] = value
        return patch if patch else _NO_CHANGE
    if before == after and type(before) is type(after):
        return _NO_CHANGE
    return after


class _NoChange:
    pass


_NO_CHANGE = _NoChange()


def render_merge_patch(before, after):
    """Serialize a merge patch. jd represents equality as an empty object."""
    value = merge_patch(before, after)
    if value is _NO_CHANGE:
        value = {}
    return _json(value)


def json_patch(before, after):
    """Return jd's test/remove/add JSON Patch operation sequence."""
    ops = []

    def walk(a, b, parts):
        if type(a) is type(b) and a == b:
            return
        path = _pointer(parts)
        if isinstance(a, dict) and isinstance(b, dict):
            for key in sorted(a):
                p = parts + [key]
                if key not in b:
                    ops.append({"op": "test", "path": _pointer(p), "value": a[key]})
                    ops.append({"op": "remove", "path": _pointer(p), "value": a[key]})
                else:
                    walk(a[key], b[key], p)
            for key in sorted(b.keys() - a.keys()):
                ops.append({"op": "add", "path": _pointer(parts + [key]), "value": b[key]})
            return
        if isinstance(a, list) and isinstance(b, list):
            sm = SequenceMatcher(a=[_json(x) for x in a], b=[_json(x) for x in b], autojunk=False)
            edits = [op for op in sm.get_opcodes() if op[0] != "equal"]
            # Test the immediate context on either side of each edit. jd emits
            # these tests before mutations, in source index order.
            context = set()
            for tag, i1, i2, j1, j2 in edits:
                if i1 > 0:
                    context.add(i1 - 1)
                if i2 < len(a):
                    context.add(i2)
            for idx in sorted(context):
                ops.append({"op": "test", "path": _pointer(parts + [idx]), "value": a[idx]})
            for tag, i1, i2, j1, j2 in edits:
                for idx in range(i1, i2):
                    ops.append({"op": "test", "path": _pointer(parts + [idx]), "value": a[idx]})
            # Apply edits from right to left so original positions remain valid.
            for tag, i1, i2, j1, j2 in reversed(edits):
                for idx in range(i2 - 1, i1 - 1, -1):
                    ops.append({"op": "remove", "path": _pointer(parts + [idx]), "value": a[idx]})
                for offset, value in enumerate(b[j1:j2]):
                    ops.append({"op": "add", "path": _pointer(parts + [i1 + offset]), "value": value})
            return
        if parts:
            ops.extend([
                {"op": "test", "path": path, "value": a},
                {"op": "remove", "path": path, "value": a},
                {"op": "add", "path": path, "value": b},
            ])
        else:
            # The jd subset does not use a root replace operation.
            ops.extend([
                {"op": "test", "path": "", "value": a},
                {"op": "remove", "path": "", "value": a},
                {"op": "add", "path": "", "value": b},
            ])

    walk(before, after, [])
    return ops


def render_json_patch(before, after):
    return _json(json_patch(before, after))

